{"command":"bun -e '
const orig = JSON.stringify({hello:"world", n:123});
const compressed = Bun.zstdCompressSync(Buffer.from(orig));
console.log("orig len", orig.length, "compressed len", compressed.length);
// Test DecompressionStream
const ds = new DecompressionStream("zstd");
const writer = ds.writable.getWriter();
const reader = ds.readable.getReader();
writer.write(compressed).then(()=>writer.close());
let out=[];
while(true){ const {done,value}=await reader.read(); if(done) break; out.push(value); }
const total = Buffer.concat(out.map(b=>Buffer.from(b)));
console.log("decompressed matches:", total.toString()===orig);
// Test Bun.zstdDecompressSync
const dec2 = Bun.zstdDecompressSync(compressed);
console.log("sync matches:", Buffer.from(dec2).toString()===orig);
' 2>&1","description":"Test zstd roundtrip APIs"}

