{"command":"bun -e '
// Test 1: Does server-side Request auto-decompress zstd?
const payload = JSON.stringify({model:"x", input:[]});
const compressed = Buffer.from(Bun.zstdCompressSync(Buffer.from(payload)));
console.log("compressed head bytes:", [...compressed.slice(0,6)].map(b=>b.toString(16)).join(" "));

const server = Bun.serve({
  port: 0,
  async fetch(req){
    const enc = req.headers.get("content-encoding");
    const raw = Buffer.from(await req.arrayBuffer());
    console.log("server saw content-encoding:", enc);
    console.log("raw len:", raw.length, "equals compressed?", raw.length===compressed.length);
    // try req.json()
    // need clone? create new request? just try JSON.parse of raw
    try {
      const j = JSON.parse(Buffer.from(raw).toString("utf8"));
      console.log("direct JSON.parse OK:", JSON.stringify(j).slice(0,50));
    } catch(e){ console.log("direct JSON.parse FAIL:", e.message.slice(0,80)); }
    try {
      // fresh read via text? body already consumed, so make new Request with same bytes+headers?
      console.log("raw as utf8 prefix:", Buffer.from(raw).toString("utf8").slice(0,50).replace(/\n/g,"\\n"));
    } catch(e){}
    return Response.json({ok:true});
  }
});
const port = server.port;
console.log("test server on", port);
// send zstd body
const res = await fetch("http://127.0.0.1:"+port+"/", {
  method: "POST",
  headers: {"Content-Type":"application/json", "Content-Encoding":"zstd"},
  body: compressed,
});
console.log("client got", res.status);
server.stop(true);
' 2>&1","description":"Test inbound zstd handling"}

