const payload = JSON.stringify({choices:[{message:{content:"hi"}}], usage:{prompt_tokens:1,completion_tokens:1,total_tokens:2}});
const compressed = Buffer.from(Bun.zstdCompressSync(Buffer.from(payload)));
console.log("payload len", payload.length, "compressed len", compressed.length);
console.log("compressed hex:", Buffer.from(compressed).toString("hex").slice(0,100));

// upstream mock that returns zstd with Content-Encoding: zstd
const upstream = Bun.serve({
  port: 0,
  fetch(req){
    console.log("upstream got accept-encoding:", req.headers.get("accept-encoding"));
    return new Response(compressed, {headers: {"Content-Type":"application/json", "Content-Encoding":"zstd"}});
  }
});
console.log("upstream", upstream.port);
const res = await fetch("http://127.0.0.1:"+upstream.port+"/", {headers: {"Accept":"application/json"}});
console.log("client content-encoding:", res.headers.get("content-encoding"));
console.log("client content-type:", res.headers.get("content-type"));
const buf = Buffer.from(await res.arrayBuffer());
console.log("client raw len:", buf.length, "first 50 hex:", buf.toString("hex").slice(0,100));
try {
  const j = await (await fetch("http://127.0.0.1:"+upstream.port+"/")).json();
  console.log("res.json() OK:", JSON.stringify(j).slice(0,80));
} catch(e){ console.log("res.json() FAIL:", e.message.slice(0,200)); }
const res2 = await fetch("http://127.0.0.1:"+upstream.port+"/");
const txt = await res2.text().catch(e=>"text fail "+e.message);
console.log("res.text() prefix:", txt.slice(0,80).replace(/\n/g,"\\n"), "len", txt.length);
upstream.stop(true);
' 2>&1","description":"Test fetch auto-decompress zstd"}

