{"command":"bun -e '
// Test streaming SSE with zstd content-encoding: does res.body yield decompressed?
const chunks = [
  JSON.stringify({choices:[{delta:{content:"hello"}}]}),
  JSON.stringify({choices:[{delta:{content:" world"}}]}),
];
const sseText = chunks.map(c=>"data: "+c+"\n\n").join("") + "data: [DONE]\n\n";
console.log("sse len", sseText.length);
const compressed = Buffer.from(Bun.zstdCompressSync(Buffer.from(sseText)));
console.log("compressed len", compressed.length);

const upstream = Bun.serve({
  port: 0,
  fetch(req){
    console.log("upstream accept-encoding:", req.headers.get("accept-encoding"));
    // Return compressed SSE with content-encoding zstd
    return new Response(compressed, {headers: {"Content-Type":"text/event-stream", "Content-Encoding":"zstd"}});
  }
});
const res = await fetch("http://127.0.0.1:"+upstream.port+"/");
console.log("client content-encoding:", res.headers.get("content-encoding"));
console.log("client content-type:", res.headers.get("content-type"));
const reader = res.body.getReader();
const decoder = new TextDecoder();
let buf="";
while(true){
  const {done,value} = await reader.read();
  if(done) break;
  console.log("chunk len", value.length, "first bytes hex", Buffer.from(value).toString("hex").slice(0,60));
  buf += decoder.decode(value, {stream:true});
}
buf += decoder.decode();
console.log("full body:", JSON.stringify(buf).slice(0,300));
upstream.stop(true);
' 2>&1","description":"Test streaming zstd decompression"}

