{"command":"bun -e '
import * as z from "node:zlib";
console.log("zstdDecompressSync?", typeof z.zstdDecompressSync);
console.log("zstdCompressSync?", typeof z.zstdCompressSync);
console.log("has ZstdDecompress?", typeof z.ZstdDecompress);
try{
  const payload = Buffer.from(JSON.stringify({a:1}));
  const comp = Bun.zstdCompressSync(payload);
  console.log("bun comp len", comp.length);
  if(typeof z.zstdDecompressSync==="function"){
    const dec = z.zstdDecompressSync(Buffer.from(comp));
    console.log("node zstd dec ok?", dec.toString()===payload.toString());
  }
}catch(e){console.log("err",e.message)}
try{
  const {brotliCompressSync, brotliDecompressSync, gunzipSync, gzipSync, inflateSync, deflateSync} = await import("node:zlib");
  console.log("brotli?", typeof brotliDecompressSync);
  const p = Buffer.from("hello world hello world");
  const c = brotliCompressSync(p);
  console.log("brotli roundtrip?", brotliDecompressSync(c).toString()===p.toString());
  const g = gzipSync(p);
  console.log("gzip magic", [...g.slice(0,2)]);
  console.log("gunzip ok?", gunzipSync(g).toString()===p.toString());
  const d = deflateSync(p);
  console.log("deflate magic", [...d.slice(0,2)]);
  console.log("inflate ok?", inflateSync(d).toString()===p.toString());
}catch(e){console.log("zlib err",e.message)}
' 2>&1","description":"Test node zlib availability"}

