{"content":"// Content-encoding helpers: the desktop client and some upstreams send
// zstd/gzip/deflate/br bodies. Bun's fetch auto-decompresses when
// Content-Encoding is present, but Bun.serve does NOT decompress inbound
// bodies, and some upstreams send raw compressed frames without any
// Content-Encoding header. All gateway JSON/SSE reads go through here so
// both labeled and magic-sniffed frames decode correctly.

import {
  brotliDecompressSync,
  gunzipSync,
  inflateRawSync,
  inflateSync,
} from "node:zlib";

function nodeZstdDecompressSync(input) {
  // node:zlib ships zstd on recent runtimes; prefer it, fall back to Bun.
  try {
    const zlib = require("node:zlib");
    if (zlib && typeof zlib.zstdDecompressSync === "function") {
      return zlib.zstdDecompressSync(input);
    }
  } catch {}
  return Bun.zstdDecompressSync(input);
}

export function parseContentEncoding(header) {
  if (!header || typeof header !== "string") return [];
  return header
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean)
    .filter((v) => v !== "identity");
}

export function sniffEncoding(buf) {
  if (!buf || buf.length < 2) return null;
  if (
    buf.length >= 4 &&
    buf[0] === 0x28 &&
    buf[1] === 0xb5 &&
    buf[2] === 0x2f &&
    buf[3] === 0xfd
  ) {
    return "zstd";
  }
  if (buf[0] === 0x1f && buf[1] === 0x8b) return "gzip";
  // zlib-wrapped deflate: 0x78 01 / 0x78 9c / 0x78 da are the common headers.
  if (buf[0] === 0x78 && (buf[1] === 0x01 || buf[1] === 0x9c || buf[1] === 0xda)) {
    return "deflate";
  }
  return null;
}

function decompressOne(buf, encoding) {
  const input = Buffer.isBuffer(buf) ? buf : Buffer.from(buf);
  switch (encoding) {
    case "zstd":
    case "x-zstd":
    case "zstandard":
      return Buffer.from(nodeZstdDecompressSync(input));
    case "gzip":
    case "x-gzip":
      return Buffer.from(gunzipSync(input));
    case "deflate":
      try {
        return Buffer.from(inflateSync(input));
      } catch {
        return Buffer.from(inflateRawSync(input));
      }
    case "br":
    case "brotli":
      return Buffer.from(brotliDecompressSync(input));
    default:
      throw new Error("unsupported content-encoding: " + encoding);
  }
}

// Decompress `bytes` according to the Content-Encoding header (applied in
// reverse, per RFC) plus magic-byte sniffing for raw frames that arrive
// without a header. Already-plain bodies (e.g. fetch already decompressed
// but left the header in place) pass through untouched: decompressing plain
// JSON throws, and we keep the original bytes.
export function decompressBuffer(bytes, contentEncodingHeader) {
  let buf = Buffer.isBuffer(bytes) ? bytes : Buffer.from(bytes || []);
  if (!buf.length) return buf;
  const encodings = parseContentEncoding(contentEncodingHeader);
  for (let i = encodings.length - 1; i >= 0; i -= 1) {
    const enc = encodings[i];
    try {
      buf = decompressOne(buf, enc);
    } catch {
      // Keep bytes as-is; sniffing below may still apply.
    }
  }
  for (let iter = 0; iter < 3; iter += 1) {
    const sniffed = sniffEncoding(buf);
    if (!sniffed) break;
    // If the header already named this encoding we attempted it above. When
    // that attempt succeeded `buf` would now be plain and sniff would be
    // null, so reaching here with the same name means the header attempt
    // failed and retrying would fail identically — but a raw frame without a
    // header still needs one attempt. Attempt once more only when the header
    // did NOT already cover it, otherwise stop.
    if (encodings.includes(sniffed)) break;
    try {
      buf = decompressOne(buf, sniffed);
    } catch {
      break;
    }
  }
  return buf;
}

export function decodeBodyToString(bytes, contentEncodingHeader) {
  return decompressBuffer(bytes, contentEncodingHeader).toString("utf8");
}

export function parseJsonBody(bytes, contentEncodingHeader) {
  return JSON.parse(decodeBodyToString(bytes, contentEncodingHeader));
}

// Robust upstream JSON read: fetch usually decompresses labeled bodies, but
// raw zstd/gzip frames without Content-Encoding arrive still compressed.
// Sniff the magic bytes so both cases parse. Returns `fallback` on failure
// to preserve the previous `res.json().catch(() => ({}))` contract.
export async function readUpstreamJson(res, fallback) {
  const fb = fallback !== undefined ? fallback : {};
  try {
    const raw = Buffer.from(await res.arrayBuffer());
    const enc = res && res.headers ? res.headers.get("content-encoding") : null;
    const buf = decompressBuffer(raw, enc);
    const text = buf.toString("utf8").trim();
    if (!text) return fb;
    return JSON.parse(text);
  } catch {
    return fb;
  }
}

// Same idea for upstream error bodies: prefer a decompressed message.
export async function readUpstreamText(res) {
  try {
    const raw = Buffer.from(await res.arrayBuffer());
    // arrayBuffer() consumes the body; callers must not read it again.
    const enc = res && res.headers ? res.headers.get("content-encoding") : null;
    return decompressBuffer(raw, enc).toString("utf8");
  } catch {
    return "";
  }
}

// Collect an upstream streaming body (SSE) into decompressed bytes. Plain
// streams pass through; raw compressed frames without a header are inflated
// first. Callers split the returned text into SSE blocks as usual.
export async function readUpstreamStreamBytes(res) {
  const raw = Buffer.from(await res.arrayBuffer());
  const enc = res && res.headers ? res.headers.get("content-encoding") : null;
  return decompressBuffer(raw, enc);
}
