{"command":"bun -e '
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import {gzipSync} from "node:zlib";

async function testUpstream(name, makeBody, headers, stream){
  const dir = mkdtempSync(path.join(tmpdir(), "codextras-up-"));
  const configPath = path.join(dir, "codextras.json");
  const mock = Bun.serve({port:0, async fetch(req){
    const {body, h} = makeBody();
    return new Response(body, {headers:h});
  }});
  writeFileSync(configPath, JSON.stringify({gateway:{port:0,pathPrefix:"/_codextras"},providers:[{id:"mock",type:"openai-chat",baseUrl:"http://127.0.0.1:"+mock.port,apiKeyEnv:"K"}],models:[{alias:"m",provider:"mock",upstreamModel:"u"}]}));
  process.env.CODEXTRAS_CONFIG=configPath;
  const {createServer}=await import("./src/server.mjs");
  const {loadConfig}=await import("./src/config.mjs");
  const server=createServer(loadConfig(),"s3cr3t");
  const base="http://127.0.0.1:"+server.port+"/_codextras/s3cr3t";
  function user(t){return {type:"message",role:"user",content:[{type:"input_text",text:t}] }}
  const r=await fetch(base+"/v1/responses",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:"m",input:[user("hi")],stream})});
  if(!stream){
    const j=await r.json();
    const txt=JSON.stringify(j);
    const ok = txt.includes("upstream-"+name);
    console.log(name+" upstream non-stream: status",r.status, ok?"PASS":"FAIL", txt.slice(0,200));
  } else {
    const txt=await r.text();
    const ok = txt.includes("upstream-"+name);
    console.log(name+" upstream stream: status",r.status, ok?"PASS":"FAIL", txt.slice(0,300).replace(/\n/g," | "));
  }
  server.stop(true); mock.stop(true);
}

function jsonPayload(tag){
  return {id:"chatcmpl-mock",object:"chat.completion",choices:[{index:0,message:{role:"assistant",content:"upstream-"+tag,reasoning_content:"r"},finish_reason:"stop"}],usage:{prompt_tokens:1,completion_tokens:1,total_tokens:2}};
}
function ssePayload(tag){
  return "data: "+JSON.stringify({choices:[{delta:{content:"upstream-"+tag}}]})+"\n\n"+"data: [DONE]\n\n";
}

// raw zstd json no header
await testUpstream("zstd-raw-json", ()=>{ const c=Buffer.from(Bun.zstdCompressSync(Buffer.from(JSON.stringify(jsonPayload("zstd-raw-json"))))); return {body:c, h:{"Content-Type":"application/json"}}; }, null, false);
// zstd with header
await testUpstream("zstd-hdr-json", ()=>{ const c=Buffer.from(Bun.zstdCompressSync(Buffer.from(JSON.stringify(jsonPayload("zstd-hdr-json"))))); return {body:c, h:{"Content-Type":"application/json","Content-Encoding":"zstd"}}; }, null, false);
// gzip raw
await testUpstream("gzip-raw-json", ()=>{ const c=gzipSync(Buffer.from(JSON.stringify(jsonPayload("gzip-raw-json")))); return {body:c, h:{"Content-Type":"application/json"}}; }, null, false);
// raw zstd SSE
await testUpstream("zstd-raw-sse", ()=>{ const c=Buffer.from(Bun.zstdCompressSync(Buffer.from(ssePayload("zstd-raw-sse")))); return {body:c, h:{"Content-Type":"text/event-stream"}}; }, null, true);
// zstd hdr SSE
await testUpstream("zstd-hdr-sse", ()=>{ const c=Buffer.from(Bun.zstdCompressSync(Buffer.from(ssePayload("zstd-hdr-sse")))); return {body:c, h:{"Content-Type":"text/event-stream","Content-Encoding":"zstd"}}; }, null, true);
// gzip raw SSE
await testUpstream("gzip-raw-sse", ()=>{ const c=gzipSync(Buffer.from(ssePayload("gzip-raw-sse"))); return {body:c, h:{"Content-Type":"text/event-stream"}}; }, null, true);
' 2>&1","description":"Verify upstream decompression"}

