const nativeMock = Bun.serve({port:0, async fetch(req){
  const body = await req.json().catch(()=>({err:"parse fail"}));
  console.log("native got body model",body.model);
  return Response.json({id:"resp_native",object:"response",status:"completed",model:body.model,output:[{type:"message",id:"m",role:"assistant",status:"completed",content:[{type:"output_text",text:"native ok "+body.model,annotations:[]}]}],usage:{input_tokens:1,output_tokens:1,total_tokens:2}});
