{"command":"bun -e '
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
// compaction with zstd upstream
let mode="ok";
const mock = Bun.serve({port:0, async fetch(req){
  const payload={id:"chatcmpl-mock",object:"chat.completion",choices:[{index:0,message:{role:"assistant",content:"summary text here",reasoning_content:""},finish_reason:"stop"}],usage:{prompt_tokens:1,completion_tokens:1,total_tokens:2}};
  let body=JSON.stringify(payload);
  if(mode==="zstd-raw"){ body=Buffer.from(Bun.zstdCompressSync(Buffer.from(body))); return new Response(body,{headers:{"Content-Type":"application/json"}}); }
  return Response.json(payload);
}});
const dir = mkdtempSync(path.join(tmpdir(), "codextras-comp-"));
const configPath = path.join(dir, "codextras.json");
writeFileSync(configPath, JSON.stringify({gateway:{port:0,pathPrefix:"/_codextras"},providers:[{id:"mock",type:"openai-chat",baseUrl:"http://127.0.0.1:"+mock.port,apiKeyEnv:"K"}],models:[{alias:"m",provider:"mock",upstreamModel:"u"}]}));
process.env.CODEXTRAS_CONFIG=configPath;
const {createServer}=await import("./src/server.mjs");
const {loadConfig}=await import("./src/config.mjs");
const server=createServer(loadConfig(),"s3cr3t");
const base="http://127.0.0.1:"+server.port+"/_codextras/s3cr3t";
function user(t){return {type:"message",role:"user",content:[{type:"input_text",text:t}] }}
mode="zstd-raw";
let r=await fetch(base+"/v1/responses/compact",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:"m",input:[user("hello")]})});
let j=await r.json();
console.log("compaction zstd-raw:",r.status, JSON.stringify(j).slice(0,300), JSON.stringify(j).includes("summary text here")?"PASS":"FAIL");
// error body zstd
mode="err";
const errMock = Bun.serve({port:0, async fetch(req){
  const errPayload={error:{message:"upstream says no"}};
  const c=Buffer.from(Bun.zstdCompressSync(Buffer.from(JSON.stringify(errPayload))));
  return new Response(c,{status:429,headers:{"Content-Type":"application/json"}});
}});
const dir2 = mkdtempSync(path.join(tmpdir(), "codextras-err-"));
const configPath2 = path.join(dir2, "codextras.json");
writeFileSync(configPath2, JSON.stringify({gateway:{port:0,pathPrefix:"/_codextras"},providers:[{id:"mock2",type:"openai-chat",baseUrl:"http://127.0.0.1:"+errMock.port,apiKeyEnv:"K"}],models:[{alias:"m2",provider:"mock2",upstreamModel:"u"}]}));
// need fresh server with new config? CONFIG_PATH cached, so manually create server with explicit config
const {loadConfig:lc2} = await import("./src/config.mjs");
// hack: set env and re-evaluate? Instead directly construct config object
const cfg2={gateway:{port:0,pathPrefix:"/_codextras"},providers:[{id:"mock2",type:"openai-chat",baseUrl:"http://127.0.0.1:"+errMock.port,apiKeyEnv:"K"}],models:[{alias:"m2",provider:"mock2",upstreamModel:"u",efforts:["high"],defaultEffort:"high"}]};
const {createServer:cs2}=await import("./src/server.mjs");
const server2=cs2(cfg2,"s2");
const base2="http://127.0.0.1:"+server2.port+"/_codextras/s2";
let r2=await fetch(base2+"/v1/responses",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:"m2",input:[user("hi")],stream:false})});
let j2=await r2.json();
console.log("error zstd-raw:",r2.status, JSON.stringify(j2).slice(0,300), JSON.stringify(j2).includes("upstream says no")?"PASS":"FAIL");
server.stop(true); mock.stop(true); server2.stop(true); errMock.stop(true);
process.exit(0);
' 2>&1","description":"Test compaction and error zstd"}

