{"command":"bun -e '
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
const errMock = Bun.serve({port:0, async fetch(req){
  const errPayload={error:{message:"upstream says no"}};
  const c=Buffer.from(Bun.zstdCompressSync(Buffer.from(JSON.stringify(errPayload))));
  return new Response(c,{status:429,headers:{"Content-Type":"application/json"}});
}});
const okMock = Bun.serve({port:0, async fetch(req){
  return Response.json({id:"x",object:"chat.completion",choices:[{message:{content:"hi"}}],usage:{prompt_tokens:1,completion_tokens:1,total_tokens:2}});
}});
const dir = mkdtempSync(path.join(tmpdir(), "codextras-err2-"));
const configPath = path.join(dir, "codextras.json");
writeFileSync(configPath, JSON.stringify({gateway:{port:0,pathPrefix:"/_codextras"},providers:[{id:"errProv",type:"openai-chat",baseUrl:"http://127.0.0.1:"+errMock.port,apiKeyEnv:"K"}],models:[{alias:"errModel",provider:"errProv",upstreamModel:"u"}]}));
process.env.CODEXTRAS_CONFIG=configPath;
const {createServer}=await import("./src/server.mjs");
const {loadConfig}=await import("./src/config.mjs");
const server=createServer(loadConfig(),"s3cr3t");
const base="http://127.0.0.1:"+server.port+"/_codextras/s3cr3t";
function user(t){return {type:"message",role:"user",content:[{type:"input_text",text:t}] }}
let r=await fetch(base+"/v1/responses",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:"errModel",input:[user("hi")],stream:false})});
let j=await r.json();
console.log("error zstd raw non-stream:",r.status, JSON.stringify(j).slice(0,300), JSON.stringify(j).includes("upstream says no")?"PASS":"FAIL");
// stream error
r=await fetch(base+"/v1/responses",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:"errModel",input:[user("hi")],stream:true})});
let txt=await r.text();
console.log("error zstd raw stream:",r.status, txt.slice(0,400).replace(/\n/g,"|"), txt.includes("upstream says no")?"PASS":"FAIL");
server.stop(true); errMock.stop(true); okMock.stop(true);
process.exit(0);
' 2>&1","description":"Test error body correctly"}

