{"command":"bun -e '
import {decompressBuffer} from "./src/encoding.mjs";
import {gzipSync} from "node:zlib";
const p=JSON.stringify({double:"test"});
const zstded=Buffer.from(Bun.zstdCompressSync(Buffer.from(p)));
const double=gzipSync(zstded);
console.log("double len",double.length);
const dec=decompressBuffer(double,"zstd, gzip");
console.log("double decode",dec.toString()===p?"PASS":"FAIL",dec.toString().slice(0,50));
// reverse header order should also? Actually correct order is zstd, gzip (zstd first). Test wrong order fails gracefully?
const dec2=decompressBuffer(double,"gzip, zstd");
console.log("wrong order decode still?",dec2.toString().slice(0,50));
process.exit(0);
' 2>&1","description":"Test double encoding"}

