{"command":"bun -e '
const orig = Buffer.from(JSON.stringify({a:1}));
const raw = orig.buffer.slice(orig.byteOffset, orig.byteOffset+orig.byteLength);
console.log("raw len",raw.byteLength);
// simulate our code: Buffer.from(raw) then slice
import {decompressBuffer} from "./src/encoding.mjs";
const dec = decompressBuffer(Buffer.from(raw), null);
console.log("dec len",dec.length, dec.toString());
const fwd = dec.buffer.slice(dec.byteOffset, dec.byteOffset+dec.byteLength);
console.log("fwd len",fwd.byteLength, Buffer.from(fwd).toString());
console.log(fwd.byteLength===raw.byteLength && Buffer.from(fwd).toString()===orig.toString()?"PASS":"FAIL");
process.exit(0);
' 2>&1","description":"Verify forwardBody slicing"}

